import test from 'node:test';
import assert from 'node:assert/strict';
import {create,project,replayPolicy,validate,render,describe} from './model.js';
const policy=(s,mode)=>({...structuredClone(s),policy:{terms:mode,format:mode,method:mode,rule:mode}});
test('handoffs name the actual incompatible fields and obey an inclusive allowance',()=>{const s=create(),r=project(s);assert.equal(r.links[0].perHandoff,8);assert.deepEqual(r.links[0].gaps.map(g=>g.dimension),['Terminology','Interface format']);assert.equal(r.links[0].completed,0);s.allowance=8;assert.equal(project(s).links[0].completed,12);});
test('unused internal dimensions do not magically improve every handoff',()=>{const s=create(),before=project(s);s.policy.method='common';const after=project(s);assert.equal(after.links[0].perHandoff,before.links[0].perHandoff);assert.equal(after.links[1].perHandoff,before.links[1].perHandoff);assert.ok(after.workaround>before.workaround);});
test('common standards replace translation with explicit local workarounds',()=>{const s=policy(create(),'common'),r=project(s);assert.equal(r.completed,r.requested);assert.equal(r.translation,0);assert.equal(r.setup,4*3*s.setup);assert.equal(r.teams[1].workarounds.length,0);assert.equal(r.teams[0].workarounds.find(w=>w.dimension==='Internal method').minutes,12*5);assert.equal(r.effort,r.setup+r.translation+r.workaround);});
test('standard versus mapping effort reverses as handoff frequency changes at equal completion',()=>{const s=create(),mapped=project(policy(s,'mapped')),common=project(policy(s,'common'));assert.equal(mapped.completed,common.completed);assert.ok(mapped.effort<common.effort);s.handoffs=[100,100,100];const denseMapped=project(policy(s,'mapped')),denseCommon=project(policy(s,'common'));assert.equal(denseMapped.completed,denseCommon.completed);assert.ok(denseCommon.effort<denseMapped.effort);});
test('matching local choices need no intervention; no handoffs cannot create a benefit',()=>{const s=create('shared'),local=project(s),common=project(policy(s,'common'));assert.equal(local.completed,72);assert.equal(local.effort,0);assert.equal(common.workaround,0);assert.ok(common.effort>local.effort);s.handoffs=[0,0,0];assert.equal(project(s).requested,0);assert.equal(project(policy(s,'mapped')).completed,0);});
test('pinned replay holds external workload and costs constant and does not mutate',()=>{const current=create('islands'),pin=policy(create(),'common');const before=JSON.stringify([current,pin]);assert.deepEqual(replayPolicy(current,pin),project({...current,policy:pin.policy}));assert.equal(JSON.stringify([current,pin]),before);});
test('bounded native validation rejects unknown or malformed data',()=>{for(const alter of [s=>s.jobs.push(5),s=>s.jobs[0]=NaN,s=>s.handoffs[1]=-1,s=>s.policy.terms='invented',s=>s.extra=true,s=>delete s.setup]){const s=create();alter(s);assert.throws(()=>validate(s));}});
test('article and portable description show the same mechanism result',()=>{const s=policy(create(),'mapped'),r=project(s);for(const width of [320,390,900]){const view=render(s,{width});assert.match(view.svg,/<svg/);assert.ok(view.summary.includes(`${r.completed} of ${r.requested}`));assert.ok(!view.svg.includes('NaN'));}assert.ok(describe(s).includes(`${r.effort} minutes`));});
